  RawFloat_MulAddExp2 mulAddExp2 (
    .clock            (clock),
    .io_in_exp2       (io_in_cmd),
    .io_in_a_isZero   (io_in_a_exp == 8'h0),
    .io_in_a_isInf    ((&io_in_a_exp) & ~(|io_in_a_mantissa)),
    .io_in_a_isNaN    ((&io_in_a_exp) & (|io_in_a_mantissa)),
    .io_in_a_sign     (io_in_a_sign),
    .io_in_a_exp      ({1'h0, io_in_a_exp} - 9'h7F),
    .io_in_a_mantissa ({1'h1, io_in_a_mantissa}),
    .io_in_b_isZero   (io_in_b_exp == 8'h0),
    .io_in_b_isInf    ((&io_in_b_exp) & ~(|io_in_b_mantissa)),
    .io_in_b_isNaN    ((&io_in_b_exp) & (|io_in_b_mantissa)),
    .io_in_b_sign     (io_in_b_sign),
    .io_in_b_exp      ({1'h0, io_in_b_exp} - 9'h7F),
    .io_in_b_mantissa ({1'h1, io_in_b_mantissa}),
    .io_in_c_isZero   (io_in_c_exp == 8'h0),
    .io_in_c_isInf    ((&io_in_c_exp) & ~(|io_in_c_mantissa)),
    .io_in_c_isNaN    ((&io_in_c_exp) & (|io_in_c_mantissa)),
    .io_in_c_sign     (io_in_c_sign),
    .io_in_c_exp      ({1'h0, io_in_c_exp} - 9'h7F),
    .io_in_c_mantissa ({1'h1, io_in_c_mantissa}),
    .io_out_isZero    (_mulAddExp2_io_out_isZero),
    .io_out_isInf     (_mulAddExp2_io_out_isInf),
    .io_out_isNaN     (_mulAddExp2_io_out_isNaN),
    .io_out_sign      (_mulAddExp2_io_out_sign),
    .io_out_exp       (_mulAddExp2_io_out_exp),
    .io_out_mantissa  (_mulAddExp2_io_out_mantissa)
  );
  assign io_out_accType_sign = _mulAddExp2_io_out_sign & ~_mulAddExp2_io_out_isNaN;
  assign io_out_accType_exp =
    _mulAddExp2_io_out_isInf | _mulAddExp2_io_out_isNaN | io_out_accType_overflow
      ? 8'hFF
      : _mulAddExp2_io_out_isZero | io_out_accType_underflow
          ? 8'h0
          : io_out_accType_roundedExp[7:0] + 8'h7F;
  assign io_out_accType_mantissa =
    _mulAddExp2_io_out_isNaN
      ? 23'h400000
      : _mulAddExp2_io_out_isZero | _mulAddExp2_io_out_isInf | io_out_accType_underflow
        | io_out_accType_overflow
          ? 23'h0
          : io_out_accType_roundedMantissa[22:0];
endmodule

module A70AccumulatorMiter(
  input         clock,
                reset,
  input  [31:0] io_a,
                io_b,
                io_c,
  input         io_exp2,
  output [31:0] io_gold,
                io_gate,
  output        io_mismatch
);

  wire        _gate_io_out_accType_sign;
  wire [7:0]  _gate_io_out_accType_exp;
  wire [22:0] _gate_io_out_accType_mantissa;
  wire        _gold_io_out_isZero;
  wire        _gold_io_out_isInf;
  wire        _gold_io_out_isNaN;
  wire        _gold_io_out_sign;
  wire [10:0] _gold_io_out_exp;
  wire [25:0] _gold_io_out_mantissa;
  wire [23:0] io_gold_roundedMantissa =
    {1'h0, _gold_io_out_mantissa[24:2]}
    + {23'h0,
       _gold_io_out_mantissa[1] & _gold_io_out_mantissa[0] | _gold_io_out_mantissa[1]
         & ~(_gold_io_out_mantissa[0]) & _gold_io_out_mantissa[2]};
  wire [11:0] io_gold_roundedExp =
    {_gold_io_out_exp[10], _gold_io_out_exp} + {11'h0, io_gold_roundedMantissa[23]};
  wire        io_gold_overflow = $signed(io_gold_roundedExp) > 12'sh7F;
  wire        io_gold_underflow = $signed(io_gold_roundedExp) < -12'sh7E;
  wire [31:0] io_gold_0 =
    {_gold_io_out_sign & ~_gold_io_out_isNaN,
     _gold_io_out_isInf | _gold_io_out_isNaN | io_gold_overflow
       ? 8'hFF
       : _gold_io_out_isZero | io_gold_underflow ? 8'h0 : io_gold_roundedExp[7:0] + 8'h7F,
     _gold_io_out_isNaN
       ? 23'h400000
       : _gold_io_out_isZero | _gold_io_out_isInf | io_gold_underflow | io_gold_overflow
           ? 23'h0
           : io_gold_roundedMantissa[22:0]};
  wire [31:0] io_gate_0 =
    {_gate_io_out_accType_sign, _gate_io_out_accType_exp, _gate_io_out_accType_mantissa};
  reg  [31:0] expected_r;
  reg  [31:0] expected_r_1;
  reg  [31:0] expected;
  reg         valid_r;
  reg         valid_r_1;
  reg         valid;
  always @(posedge clock) begin
    expected_r <= io_gold_0;
    expected_r_1 <= expected_r;
    expected <= expected_r_1;
    if (reset) begin
      valid_r <= 1'h0;
      valid_r_1 <= 1'h0;
      valid <= 1'h0;
    end
    else begin
      valid_r <= ~reset;
      valid_r_1 <= valid_r;
      valid <= valid_r_1;
    end
  end // always @(posedge)
  A70LegacyRawFloat_MulAddExp2 gold (
    .io_in_exp2       (io_exp2),
    .io_in_a_isZero   (io_a[30:23] == 8'h0),
    .io_in_a_isInf    ((&(io_a[30:23])) & ~(|(io_a[22:0]))),
    .io_in_a_isNaN    ((&(io_a[30:23])) & (|(io_a[22:0]))),
    .io_in_a_sign     (io_a[31]),
    .io_in_a_exp      ({1'h0, io_a[30:23]} - 9'h7F),
    .io_in_a_mantissa ({1'h1, io_a[22:0]}),
    .io_in_b_isZero   (io_b[30:23] == 8'h0),
    .io_in_b_isInf    ((&(io_b[30:23])) & ~(|(io_b[22:0]))),
    .io_in_b_isNaN    ((&(io_b[30:23])) & (|(io_b[22:0]))),
    .io_in_b_sign     (io_b[31]),
    .io_in_b_exp      ({1'h0, io_b[30:23]} - 9'h7F),
    .io_in_b_mantissa ({1'h1, io_b[22:0]}),
    .io_in_c_isZero   (io_c[30:23] == 8'h0),
    .io_in_c_isInf    ((&(io_c[30:23])) & ~(|(io_c[22:0]))),
    .io_in_c_isNaN    ((&(io_c[30:23])) & (|(io_c[22:0]))),
    .io_in_c_sign     (io_c[31]),
    .io_in_c_exp      ({1'h0, io_c[30:23]} - 9'h7F),
    .io_in_c_mantissa ({1'h1, io_c[22:0]}),
    .io_out_isZero    (_gold_io_out_isZero),
    .io_out_isInf     (_gold_io_out_isInf),
    .io_out_isNaN     (_gold_io_out_isNaN),
    .io_out_sign      (_gold_io_out_sign),
    .io_out_exp       (_gold_io_out_exp),
    .io_out_mantissa  (_gold_io_out_mantissa)
  );
  FPAccUnit gate (
    .clock                   (clock),
    .io_in_a_sign            (io_a[31]),
    .io_in_a_exp             (io_a[30:23]),
    .io_in_a_mantissa        (io_a[22:0]),
    .io_in_b_sign            (io_b[31]),
    .io_in_b_exp             (io_b[30:23]),
    .io_in_b_mantissa        (io_b[22:0]),
    .io_in_c_sign            (io_c[31]),
    .io_in_c_exp             (io_c[30:23]),
    .io_in_c_mantissa        (io_c[22:0]),
    .io_in_cmd               (io_exp2),
    .io_out_accType_sign     (_gate_io_out_accType_sign),
    .io_out_accType_exp      (_gate_io_out_accType_exp),
    .io_out_accType_mantissa (_gate_io_out_accType_mantissa)
  );
  assign io_gold = io_gold_0;
  assign io_gate = io_gate_0;
  assign io_mismatch = valid & io_gate_0 != expected;
endmodule

